from typing import Any

from django.core.exceptions import ValidationError

from bloomerp.models.communication.instant_messaging.im_message import IMMessage
from bloomerp.tests.base import (
    BloomerpModelTestCase,
    ExpectedModelException,
    ModelScenario,
)

from .fixtures import IMFixtures


class TestImmessageModel(IMFixtures, BloomerpModelTestCase):
    """Cover quotes, one-level threads, idempotency and immutable provenance."""

    model = IMMessage

    def linked_args(self) -> dict[str, Any]:
        """Quote a specific reply while remaining in its root thread."""
        return self.args("message", reply_to=self.reply, thread_root=self.root)

    def duplicate_args(self) -> dict[str, Any]:
        """Simulate a repeated client send using the same idempotency key."""
        IMMessage.objects.create(**self.args("message", client_id="retry"))
        return self.args("message", sequence=4, client_id="retry")

    def get_test_scenarios(self) -> list[ModelScenario[IMMessage]]:
        """Declare cross-conversation and ordering invariants on persisted messages."""
        return [
            self.scenario("Create a message", "message"),
            ModelScenario(
                name="Quoted thread reply",
                preparation=self.prepare,
                create_args=self.linked_args,
            ),
            self.invalid_relation("message", "sender", "other_participant"),
            self.invalid_relation("message", "reply_to", "foreign"),
            self.invalid_relation("message", "thread_root", "reply"),
            self.scenario(
                "Reject duplicate sequence", "message", sequence=1, invalid=True
            ),
            ModelScenario(
                name="Reject retried client ID",
                preparation=self.prepare,
                create_args=self.duplicate_args,
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
            ModelScenario(
                name="Do not rewrite message sequence",
                preparation=self.prepare,
                create_args=partial(self.args, "message"),
                update_args={"sequence": 5},
                expected_exceptions=[ExpectedModelException("update", ValidationError)],
            ),
        ]
